const EMPTY_DEMAND_GIF = "data:image/gif;base64,";

const IS_COORD  = c => c === 'Coordenador de Eventos';
const IS_MEMBER = c => c === 'Membro de Eventos' || c === 'Coordenador de Eventos';

// ── Utilitários ───────────────────────────────────────────────────────────────
function comprimirImagem(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = e => {
      const img = new Image();
      img.onload = () => {
        const MAX = 1080, ratio = Math.min(MAX/img.width, MAX/img.height, 1);
        const canvas = document.createElement('canvas');
        canvas.width = img.width*ratio; canvas.height = img.height*ratio;
        canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
        let q = 0.82;
        const tryIt = () => {
          const d = canvas.toDataURL('image/jpeg', q);
          if ((d.length*3/4/1024) <= 700 || q <= 0.2) resolve(d);
          else { q -= 0.1; tryIt(); }
        };
        tryIt();
      };
      img.onerror = reject; img.src = e.target.result;
    };
    reader.onerror = reject; reader.readAsDataURL(file);
  });
}

function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = e => resolve(e.target.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function prazoLabel(ts) {
  if (!ts) return '';
  const d = ts.toDate ? ts.toDate() : new Date(ts);
  const diff = d - new Date();
  if (diff < 0) return '⏰ Prazo encerrado';
  const h = Math.floor(diff / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  if (h >= 24) return `📅 ${Math.floor(h/24)}d ${h%24}h restantes`;
  return `⏳ ${h}h ${m}m restantes`;
}

function prazoColor(ts) {
  if (!ts) return 'var(--muted)';
  const diff = (ts.toDate ? ts.toDate() : new Date(ts)) - new Date();
  if (diff < 0) return '#e87f7f';
  if (diff < 3600000*6) return '#e87f7f';
  if (diff < 3600000*24) return '#C9A44A';
  return '#4caf8a';
}

