function NovaDemandaModal({ user, onClose }) {
  const [titulo, setTitulo]     = useState('');
  const [descricao, setDescricao] = useState('');
  const [prazo, setPrazo]       = useState('');
  const [maxPart, setMaxPart]   = useState(1);
  const [imgBase64, setImgBase64] = useState(null);
  const [imgPreview, setImgPreview] = useState(null);
  const [loading, setLoading]   = useState(false);
  const [compressing, setCompressing] = useState(false);
  const [erro, setErro]         = useState('');
  const fileRef = useRef();

  const handleImg = async e => {
    const file = e.target.files[0]; if (!file) return;
    setCompressing(true);
    try { const c = await comprimirImagem(file); setImgBase64(c); setImgPreview(c); }
    catch { setErro('Erro ao processar imagem.'); }
    setCompressing(false);
  };

  const criar = async () => {
    if (!titulo.trim() || !descricao.trim() || !prazo) { setErro('Preencha título, descrição e prazo.'); return; }
    setLoading(true); setErro('');
    try {
      const expiracao24h = new Date(Date.now() + 24*60*60*1000);
      const prazoDate    = new Date(prazo);
      await addDoc(collection(db, 'demandas_eventos'), {
        titulo: titulo.trim(), descricao: descricao.trim(),
        imagem: imgBase64 || null,
        prazo: prazoDate, expiracao24h,
        maxParticipantes: maxPart,
        participantes: [],
        status: 'aguardando',
        criadoPor: user.nome, criadoPorId: user.matricula,
        criadoEm: serverTimestamp(),
      });
      // Notifica membros de marketing sobre nova demanda
      try {
        const { getDocs } = await import('firebase/firestore');
        const mSnap = await getDocs(query(collection(db,'usuarios'),
          where('cargo','in',['Membro de Eventos','Coordenador de Eventos'])));
        for (const m of mSnap.docs) {
          if (m.data().matricula !== user.matricula) {
            await criarNotificacao(m.data().matricula, '📋 Nova demanda de Eventos disponível',
              `"${titulo.trim()}" — você tem 24h para aceitar!`, 'nova_demanda_eventos');
          }
        }
      } catch {}
      onClose();
    } catch { setErro('Erro ao criar demanda.'); setLoading(false); }
  };

  return (
    <div style={modalWrap}>
      <div style={modalHeader}>
        <button onClick={onClose} style={btnCancel}>Cancelar</button>
        <span style={modalTitle}>Nova Demanda</span>
        <button onClick={criar} disabled={loading||compressing} style={btnPublish}>{loading?'...':'Criar'}</button>
      </div>
      <div style={{ flex:1, overflowY:'auto', padding:16 }}>
        <div style={{ marginBottom:14 }}>
          <label style={lbl}>📋 Título da demanda</label>
          <input value={titulo} onChange={e=>{setTitulo(e.target.value);setErro('');}} placeholder="Ex: Post para o Instagram" style={inp} />
        </div>
        <div style={{ marginBottom:14 }}>
          <label style={lbl}>📝 Descrição</label>
          <textarea value={descricao} onChange={e=>{setDescricao(e.target.value);setErro('');}} placeholder="Descreva o que precisa ser feito..." style={{ ...taStyle, minHeight:90 }} />
        </div>
        <div style={{ marginBottom:14 }}>
          <label style={lbl}>📅 Prazo de entrega</label>
          <input type="datetime-local" value={prazo} onChange={e=>{setPrazo(e.target.value);setErro('');}}
            style={{ ...inp, colorScheme:'dark' }} />
        </div>
        <div style={{ marginBottom:14 }}>
          <label style={lbl}>👥 Máximo de participantes</label>
          <div style={{ display:'flex', gap:8 }}>
            {[1,2,3,4,5].map(n => (
              <button key={n} onClick={()=>setMaxPart(n)}
                style={{ flex:1, padding:'10px 0', borderRadius:12, border:maxPart===n?'none':'1px solid var(--border2)', background:maxPart===n?'var(--gold)':'var(--card)', color:maxPart===n?'var(--bg)':'var(--muted)', fontSize:14, fontWeight:700, fontFamily:'var(--font-body)' }}>
                {n}
              </button>
            ))}
          </div>
        </div>
        <div style={{ marginBottom:14 }}>
          <label style={lbl}>🖼️ Imagem de referência (opcional)</label>
          <input ref={fileRef} type="file" accept="image/*,.pdf,.doc,.docx" onChange={handleImg} style={{ display:'none' }} />
          <button onClick={()=>fileRef.current.click()} disabled={compressing} style={uploadBtn}>
            {compressing?'⏳ Processando...':`📎 ${imgPreview?'Trocar':'Adicionar'} imagem ou documento`}
          </button>
          {imgPreview && (
            <div style={{ marginTop:8, position:'relative', borderRadius:12, overflow:'hidden' }}>
              <img src={imgPreview} alt="" style={{ width:'100%', maxHeight:180, objectFit:'cover', display:'block' }} />
              <button onClick={()=>{setImgBase64(null);setImgPreview(null);}} style={removeImgBtn}>×</button>
            </div>
          )}
        </div>
        <div style={{ background:'rgba(201,164,74,.08)', border:'1px solid rgba(201,164,74,.2)', borderRadius:12, padding:12, fontSize:12, color:'var(--cream)', lineHeight:1.6 }}>
          ⚠️ <strong>Regras automáticas:</strong><br />
          • Membros têm <strong>24h</strong> para aceitar a demanda<br />
          • Se ninguém aceitar em 24h → <strong>-30 XP</strong> para todos os membros<br />
          • Entrega dentro do prazo → <strong>+60 XP</strong><br />
          • Entrega fora do prazo → <strong>-50 XP</strong>
        </div>
        {erro && <div style={{ ...erroBox, marginTop:12 }}>⚠️ {erro}</div>}
      </div>
    </div>
  );
}

function EnvioDemandaModal({ demanda, user, onClose }) {
  const [arquivo, setArquivo]   = useState(null);
  const [preview, setPreview]   = useState(null);
  const [tipo, setTipo]         = useState('');
  const [loading, setLoading]   = useState(false);
  const [erro, setErro]         = useState('');
  const fileRef = useRef();

  const handleFile = async e => {
    const file = e.target.files[0]; if (!file) return;
    const isImg = file.type.startsWith('image/');
    try {
      const b64 = isImg ? await comprimirImagem(file) : await fileToBase64(file);
      setArquivo(b64); setTipo(isImg ? 'imagem' : 'documento');
      if (isImg) setPreview(b64); else setPreview(null);
      setErro('');
    } catch { setErro('Erro ao processar arquivo.'); }
  };

  const enviar = async () => {
    if (!arquivo) { setErro('Selecione um arquivo.'); return; }
    setLoading(true); setErro('');
    try {
      // Verifica se já enviou
      const q = query(collection(db,'envios_demandas_eventos'),
        where('demandaId','==',demanda.id), where('userId','==',user.matricula));
      const snap = await (await import('firebase/firestore')).getDocs(q);
      if (!snap.empty) {
        // Atualiza envio existente
        await updateDoc(doc(db,'envios_demandas_eventos',snap.docs[0].id), {
          arquivo, tipo, enviadoEm: serverTimestamp(), status:'pendente', feedback:'',
        });
      } else {
        await addDoc(collection(db,'envios_demandas_eventos'), {
          demandaId: demanda.id, demandaTitulo: demanda.titulo,
          userId: user.matricula, userName: user.nome,
          arquivo, tipo, enviadoEm: serverTimestamp(),
          status: 'pendente', feedback: '',
        });
      }
      onClose();
    } catch { setErro('Erro ao enviar. Tente novamente.'); setLoading(false); }
  };

  return (
    <div style={modalWrap}>
      <div style={modalHeader}>
        <button onClick={onClose} style={btnCancel}>Cancelar</button>
        <span style={modalTitle}>Enviar Demanda</span>
        <button onClick={enviar} disabled={loading} style={btnPublish}>{loading?'...':'Enviar'}</button>
      </div>
      <div style={{ flex:1, overflowY:'auto', padding:16 }}>
        <div style={{ background:'var(--bg3)', border:'1px solid var(--border2)', borderRadius:14, padding:14, marginBottom:18 }}>
          <div style={{ fontSize:13, fontWeight:700, color:'var(--cream)', marginBottom:4 }}>{demanda.titulo}</div>
          <div style={{ fontSize:12, color:'var(--muted)', lineHeight:1.5 }}>{demanda.descricao}</div>
          <div style={{ fontSize:12, marginTop:6, color: prazoColor(demanda.prazo) }}>{prazoLabel(demanda.prazo)}</div>
        </div>
        <label style={lbl}>📎 Seu arquivo (imagem ou documento)</label>
        <input ref={fileRef} type="file" accept="image/*,.pdf,.doc,.docx,.ppt,.pptx" onChange={handleFile} style={{ display:'none' }} />
        <button onClick={()=>fileRef.current.click()} style={uploadBtn}>
          📎 {arquivo ? 'Trocar arquivo' : 'Selecionar arquivo'}
        </button>
        {preview && <img src={preview} alt="" style={{ marginTop:10, width:'100%', maxHeight:200, objectFit:'cover', borderRadius:12 }} />}
        {arquivo && !preview && <div style={{ marginTop:10, padding:'10px 14px', background:'var(--card)', borderRadius:10, fontSize:13, color:'var(--cream)', display:'flex', alignItems:'center', gap:8 }}>📄 Documento selecionado</div>}
        {erro && <div style={{ ...erroBox, marginTop:12 }}>⚠️ {erro}</div>}
      </div>
    </div>
  );
}


function EditarDemandaModal({ demanda, onClose }) {
  const [descricao, setDescricao] = useState(demanda.descricao || '');
  const [prazo, setPrazo]         = useState(() => {
    const d = demanda.prazo?.toDate ? demanda.prazo.toDate() : new Date(demanda.prazo);
    return d.toISOString().slice(0,16);
  });
  const [imgBase64, setImgBase64]   = useState(demanda.imagem || null);
  const [imgPreview, setImgPreview] = useState(demanda.imagem || null);
  const [loading, setLoading]       = useState(false);
  const [compressing, setCompressing] = useState(false);
  const [erro, setErro]             = useState('');
  const fileRef = useRef();

  const handleImg = async e => {
    const file = e.target.files[0]; if (!file) return;
    setCompressing(true);
    try { const c = await comprimirImagem(file); setImgBase64(c); setImgPreview(c); }
    catch { setErro('Erro ao processar imagem.'); }
    setCompressing(false);
  };

  const salvar = async () => {
    if (!descricao.trim() || !prazo) { setErro('Preencha descrição e prazo.'); return; }
    setLoading(true); setErro('');
    try {
      await updateDoc(doc(db,'demandas_eventos',demanda.id), {
        descricao: descricao.trim(),
        prazo: new Date(prazo),
        imagem: imgBase64 || null,
      });
      onClose();
    } catch { setErro('Erro ao salvar.'); setLoading(false); }
  };

  return (
    <div style={modalWrap}>
      <div style={modalHeader}>
        <button onClick={onClose} style={btnCancel}>Cancelar</button>
        <span style={modalTitle}>Editar Demanda</span>
        <button onClick={salvar} disabled={loading||compressing} style={btnPublish}>{loading?'...':'Salvar'}</button>
      </div>
      <div style={{ flex:1, overflowY:'auto', padding:16 }}>
        <div style={{ marginBottom:14 }}>
          <label style={lbl}>📝 Descrição</label>
          <textarea value={descricao} onChange={e=>{setDescricao(e.target.value);setErro('');}}
            style={{ ...taStyle, minHeight:90 }} />
        </div>
        <div style={{ marginBottom:14 }}>
          <label style={lbl}>📅 Novo prazo de entrega</label>
          <input type="datetime-local" value={prazo} onChange={e=>{setPrazo(e.target.value);setErro('');}}
            style={{ ...inp, colorScheme:'dark' }} />
        </div>
        <div style={{ marginBottom:14 }}>
          <label style={lbl}>🖼️ Imagem de referência</label>
          <input ref={fileRef} type="file" accept="image/*,.pdf,.doc,.docx" onChange={handleImg} style={{ display:'none' }} />
          <button onClick={()=>fileRef.current.click()} disabled={compressing} style={uploadBtn}>
            {compressing?'⏳ Processando...':`📎 ${imgPreview?'Trocar':'Adicionar'} imagem ou documento`}
          </button>
          {imgPreview && (
            <div style={{ marginTop:8, position:'relative', borderRadius:12, overflow:'hidden' }}>
              <img src={imgPreview} alt="" style={{ width:'100%', maxHeight:180, objectFit:'cover', display:'block' }} />
              <button onClick={()=>{setImgBase64(null);setImgPreview(null);}} style={removeImgBtn}>×</button>
            </div>
          )}
        </div>
        {erro && <div style={erroBox}>⚠️ {erro}</div>}
      </div>
    </div>
  );
}

function DemandaCard({ demanda, user, meuEnvio }) {
  const [aceitando, setAceitando]   = useState(false);
  const [showEnvio, setShowEnvio]   = useState(false);
  const [showEdit, setShowEdit]     = useState(false);
  const isCoord   = IS_COORD(user.cargo);
  const jaPeguei  = demanda.participantes?.some(p => p.userId === user.matricula);
  const lotada    = demanda.participantes?.length >= demanda.maxParticipantes;
  const c24h      = demanda.expiracao24h?.toDate ? demanda.expiracao24h.toDate() : new Date(demanda.expiracao24h);
  const expirou24h = new Date() > c24h && demanda.status === 'aguardando';

  const aceitar = async () => {
    if (lotada || jaPeguei) return;
    setAceitando(true);
    try {
      const novosPart = [...(demanda.participantes||[]), { userId: user.matricula, userName: user.nome, aceitoEm: new Date().toISOString() }];
      const novoStatus = novosPart.length >= demanda.maxParticipantes ? 'em_progresso' : demanda.status;
      await updateDoc(doc(db,'demandas_eventos',demanda.id), {
        participantes: novosPart, status: novoStatus,
      });
    } catch {}
    setAceitando(false);
  };

  const deletar = async () => {
    if (!window.confirm('Deletar esta demanda?')) return;
    await deleteDoc(doc(db,'demandas_eventos',demanda.id));
  };

  const statusColor = { aguardando:'#C9A44A', em_progresso:'#6a9fd8', encerrada:'var(--muted)' };
  const statusLabel = { aguardando:'🟡 Aguardando', em_progresso:'🔵 Em progresso', encerrada:'⚫ Encerrada' };

  return (
    <div style={{ ...card, marginBottom:14 }}>
      {/* Header */}
      <div style={{ padding:'13px 14px 0', display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
        <div style={{ flex:1 }}>
          <div style={{ fontSize:15, fontWeight:700, color:'var(--cream)', marginBottom:4 }}>{demanda.titulo}</div>
          <div style={{ fontSize:11, fontWeight:600, color: statusColor[demanda.status]||'var(--muted)', marginBottom:6 }}>
            {statusLabel[demanda.status]||demanda.status}
          </div>
        </div>
        {isCoord && (
        <div style={{ display:'flex', gap:6, marginLeft:8 }}>
          <button onClick={()=>setShowEdit(true)} style={{ ...deleteBtn, color:'var(--gold)', background:'rgba(201,164,74,.1)', border:'1px solid rgba(201,164,74,.25)' }}>✏️</button>
          <button onClick={deletar} style={deleteBtn}>🗑️</button>
        </div>
      )}
      </div>

      {/* Imagem */}
      {demanda.imagem && <img src={demanda.imagem} alt="" style={{ width:'100%', maxHeight:200, objectFit:'cover', display:'block', margin:'8px 0' }} />}

      {/* Descrição */}
      <div style={{ padding:'0 14px 10px' }}>
        <div style={{ fontSize:13, color:'var(--cream)', lineHeight:1.6, marginBottom:8 }}>{demanda.descricao}</div>

        {/* Prazo e 24h */}
        <div style={{ display:'flex', gap:8, flexWrap:'wrap', marginBottom:10 }}>
          <div style={{ fontSize:12, fontWeight:600, color: prazoColor(demanda.prazo), background:`${prazoColor(demanda.prazo)}18`, padding:'4px 10px', borderRadius:20, border:`1px solid ${prazoColor(demanda.prazo)}33` }}>
            {prazoLabel(demanda.prazo)}
          </div>
          {demanda.status === 'aguardando' && !expirou24h && (
            <div style={{ fontSize:12, color:'var(--muted)', background:'rgba(242,228,196,.06)', padding:'4px 10px', borderRadius:20, border:'1px solid var(--border)' }}>
              ⏳ {Math.max(0, Math.floor(((demanda.expiracao24h?.toDate?demanda.expiracao24h.toDate():new Date(demanda.expiracao24h)) - new Date()) / 60000))}min para aceite
            </div>
          )}
        </div>

        {/* Participantes */}
        <div style={{ fontSize:12, color:'var(--muted)', marginBottom:10 }}>
          👥 {demanda.participantes?.length||0}/{demanda.maxParticipantes} participante{demanda.maxParticipantes>1?'s':''}
          {demanda.participantes?.length > 0 && (
            <span style={{ marginLeft:8, color:'var(--cream)' }}>
              — {demanda.participantes.map(p=>p.userName).join(', ')}
            </span>
          )}
        </div>

        {/* Feedback do coordenador (só quem está na demanda vê) */}
        {jaPeguei && meuEnvio?.status === 'problema' && (
          <div style={{ background:'rgba(232,127,127,.1)', border:'1px solid rgba(232,127,127,.3)', borderRadius:12, padding:12, marginBottom:10 }}>
            <div style={{ fontSize:12, fontWeight:700, color:'#e87f7f', marginBottom:4 }}>⚠️ Problema na demanda</div>
            <div style={{ fontSize:13, color:'var(--cream)', lineHeight:1.5 }}>{meuEnvio.feedback}</div>
          </div>
        )}
        {jaPeguei && meuEnvio?.status === 'aprovado' && (
          <div style={{ background:'rgba(76,175,138,.1)', border:'1px solid rgba(76,175,138,.3)', borderRadius:12, padding:12, marginBottom:10 }}>
            <div style={{ fontSize:12, fontWeight:700, color:'#4caf8a' }}>✅ Demanda aprovada! +60 XP</div>
          </div>
        )}
        {jaPeguei && meuEnvio?.status === 'pendente' && (
          <div style={{ background:'rgba(201,164,74,.08)', border:'1px solid rgba(201,164,74,.2)', borderRadius:12, padding:10, marginBottom:10 }}>
            <div style={{ fontSize:12, color:'var(--gold)' }}>📤 Envio aguardando avaliação</div>
          </div>
        )}

        {/* Botões de ação */}
        {!isCoord && (
          <>
            {!jaPeguei && !lotada && demanda.status !== 'encerrada' && !expirou24h && (
              <button onClick={aceitar} disabled={aceitando}
                style={{ width:'100%', padding:'12px', borderRadius:12, border:'none', background:'linear-gradient(135deg,#C9A44A,#a8832e)', color:'var(--bg)', fontSize:14, fontWeight:700, fontFamily:'var(--font-body)', marginBottom:8 }}>
                {aceitando ? '⏳ Aceitando...' : '✋ Aceitar demanda'}
              </button>
            )}
            {jaPeguei && demanda.status !== 'encerrada' && !meuEnvio?.status && (() => {
              const prazoPassed = demanda.prazo && new Date() > (demanda.prazo?.toDate ? demanda.prazo.toDate() : new Date(demanda.prazo));
              if (prazoPassed) return <div style={{ textAlign:'center', fontSize:13, color:'#e87f7f', padding:'8px 0' }}>⏰ Prazo encerrado — entrega não permitida</div>;
              return (
                <button onClick={()=>setShowEnvio(true)}
                  style={{ width:'100%', padding:'12px', borderRadius:12, border:'1px solid var(--gold)', background:'rgba(201,164,74,.08)', color:'var(--gold)', fontSize:14, fontWeight:700, fontFamily:'var(--font-body)' }}>
                  📤 Enviar entrega
                </button>
              );
            })()}
            {jaPeguei && meuEnvio?.status === 'problema' && (() => {
              const prazoPassed = demanda.prazo && new Date() > (demanda.prazo?.toDate ? demanda.prazo.toDate() : new Date(demanda.prazo));
              if (prazoPassed) return <div style={{ textAlign:'center', fontSize:13, color:'#e87f7f', padding:'8px 0' }}>⏰ Prazo encerrado</div>;
              return (
                <button onClick={()=>setShowEnvio(true)}
                  style={{ width:'100%', padding:'12px', borderRadius:12, border:'1px solid #e87f7f', background:'rgba(232,127,127,.08)', color:'#e87f7f', fontSize:14, fontWeight:700, fontFamily:'var(--font-body)' }}>
                  🔄 Reenviar entrega
                </button>
              );
            })()}
            {!jaPeguei && lotada && <div style={{ textAlign:'center', fontSize:13, color:'var(--muted)', padding:'8px 0' }}>Demanda já foi aceita por outros membros</div>}
          </>
        )}
      </div>

      {showEnvio && <EnvioDemandaModal demanda={demanda} user={user} onClose={()=>setShowEnvio(false)} />}
      {showEdit  && <EditarDemandaModal demanda={demanda} onClose={()=>setShowEdit(false)} />}
    </div>
  );
}

// ── Painel do Coordenador ─────────────────────────────────────────────────────
function PainelCoordenador({ user }) {
  const [envios, setEnvios] = useState([]);
  const [loading, setLoading] = useState(true);
  const [feedback, setFeedback] = useState({});

  useEffect(() => {
    const q = query(collection(db,'envios_demandas_eventos'), where('status','==','pendente'));
    const unsub = onSnapshot(q, snap => {
      setEnvios(snap.docs.map(d=>({id:d.id,...d.data()})));
      setLoading(false);
    },
      err => { console.log('snapshot error:', err); }
    );
    return unsub;
  }, []);

  const avaliar = async (envioId, userId, status, feedbackText) => {
    try {
      await updateDoc(doc(db,'envios_demandas_eventos',envioId), {
        status, feedback: feedbackText||'', avaliadoEm: serverTimestamp(),
      });
      if (status === 'aprovado') {
        // Dar +60 XP ao membro
        const uSnap = await (await import('firebase/firestore')).getDocs(
          query(collection(db,'usuarios'), where('matricula','==',userId))
        );
        if (!uSnap.empty) {
          const uDoc = uSnap.docs[0];
          await updateDoc(doc(db,'usuarios',uDoc.id), { xp: (uDoc.data().xp||0)+60 });
        }
      }
    } catch (e) { console.error(e); }
  };

  if (loading) return <div style={{ padding:20, textAlign:'center', color:'var(--muted)' }}>Carregando...</div>;
  if (envios.length === 0) return (
    <div style={{ padding:'32px 20px', textAlign:'center' }}>
      <div style={{ fontSize:40, marginBottom:12 }}>📭</div>
      <div style={{ fontSize:14, color:'var(--muted)' }}>Nenhuma entrega pendente de avaliação.</div>
    </div>
  );

  return (
    <div style={{ padding:'0 14px', paddingBottom:24 }}>
      {envios.map(e => (
        <div key={e.id} style={{ ...card, marginBottom:12, padding:14 }}>
          <div style={{ fontSize:14, fontWeight:700, color:'var(--cream)', marginBottom:4 }}>{e.demandaTitulo}</div>
          <div style={{ fontSize:12, color:'var(--gold)', marginBottom:10 }}>👤 {e.userName} · {e.userId}</div>
          {e.tipo==='imagem'
            ? <img src={e.arquivo} alt="" style={{ width:'100%', maxHeight:200, objectFit:'cover', borderRadius:10, marginBottom:10 }} />
            : <div style={{ padding:'10px 14px', background:'var(--bg3)', borderRadius:10, marginBottom:10, fontSize:13, color:'var(--cream)', display:'flex', alignItems:'center', gap:8 }}>📄 Documento enviado</div>
          }
          <textarea
            placeholder="Escreva um feedback (obrigatório se reprovar)..."
            value={feedback[e.id]||''}
            onChange={ev=>setFeedback(f=>({...f,[e.id]:ev.target.value}))}
            style={{ ...taStyle, minHeight:70, marginBottom:10 }}
          />
          <div style={{ display:'flex', gap:8 }}>
            <button onClick={()=>avaliar(e.id, e.userId,'aprovado', '')}
              style={{ flex:1, padding:'11px', borderRadius:12, border:'none', background:'rgba(76,175,138,.15)', color:'#4caf8a', fontSize:13, fontWeight:700, fontFamily:'var(--font-body)', border:'1px solid rgba(76,175,138,.3)' }}>
              ✅ Aprovar
            </button>
            <button onClick={()=>{
              if (!(feedback[e.id]||'').trim()) { alert('Escreva o feedback antes de reprovar.'); return; }
              avaliar(e.id, e.userId,'problema', feedback[e.id]||'');
            }}
              style={{ flex:1, padding:'11px', borderRadius:12, border:'none', background:'rgba(232,127,127,.12)', color:'#e87f7f', fontSize:13, fontWeight:700, fontFamily:'var(--font-body)', border:'1px solid rgba(232,127,127,.3)' }}>
              ⚠️ Problema
            </button>
          </div>
        </div>
      ))}
    </div>
  );
}

// ── Tela Principal ────────────────────────────────────────────────────────────
export default function EventosScreen({ user }) {
  const [aba, setAba]           = useState('demandas');
  const [demandas, setDemandas] = useState([]);
  const [meusEnvios, setMeusEnvios] = useState([]);
  const [modalDemanda, setModalDemanda] = useState(false);

  const isCoord  = IS_COORD(user.cargo);
  const isMember = IS_MEMBER(user.cargo);

  const [badgeDemandas, setBadgeDemandas] = useState(0);
  const [badgeAvaliar,  setBadgeAvaliar]  = useState(0);

  useEffect(() => {
    processarDemandasExpiradas_demandas_eventos();

    const u2 = onSnapshot(
      collection(db, 'demandas_eventos'),
      s => {
        const all = s.docs.map(d => ({ id:d.id,...d.data() }));
        setDemandas(all);
        if (!isCoord) setBadgeDemandas(all.filter(d =>
          d.status === 'aguardando' &&
          !d.participantes?.some(p => p.userId === user.matricula)
        ).length);
      },
      err => { console.log('demandas err:', err); }
    );

    const u3 = onSnapshot(
      query(collection(db, 'envios_demandas_eventos'), where('userId','==',user.matricula)),
      s => setMeusEnvios(s.docs.map(d => ({ id:d.id,...d.data() }))),
      err => { console.log('envios err:', err); }
    );

    if (isCoord) {
      const u4 = onSnapshot(
        query(collection(db, 'envios_demandas_eventos'), where('status','==','pendente')),
        s => setBadgeAvaliar(s.docs.length),
        err => { console.log('avaliar err:', err); }
      );
      return () => { u2(); u3(); u4(); };
    }

    return () => { u2(); u3(); };
  }, []);


  const abas = [
    { id:'demandas', label:'📋 Demandas', badge:badgeDemandas },
    ...(isCoord ? [{ id:'avaliar', label:'🔍 Avaliar', badge:badgeAvaliar }] : []),
  ];

  return (
    <div style={{ display:'flex', flexDirection:'column', height:'100%' }}>
      {/* Header */}
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', padding:'16px 16px 10px', flexShrink:0 }}>
        <div>
          <div style={{ fontFamily:'var(--font-display)', fontSize:22, fontWeight:700, color:'var(--cream)' }}>Eventos</div>
          <div style={{ fontSize:12, color:'var(--muted)', marginTop:2 }}>{user.cargo}</div>
        </div>
        {aba==='demandas' && isCoord && (
          <button onClick={()=>setModalDemanda(true)} style={btnGold}>+ Demanda</button>
        )}
      </div>

      {/* Tabs */}
      <div style={{ display:'flex', gap:6, padding:'0 14px 12px', flexShrink:0 }}>
        {abas.map(a => (
          <button key={a.id} onClick={()=>setAba(a.id)}
            style={{ flex:1, padding:'9px 0', borderRadius:12, border:aba===a.id?'none':'1px solid var(--border)', background:aba===a.id?'linear-gradient(135deg,#C9A44A,#a8832e)':'var(--card)', color:aba===a.id?'var(--bg)':'var(--muted)', fontSize:12, fontWeight:aba===a.id?700:500, fontFamily:'var(--font-body)', position:'relative' }}>
            {a.label}
            {a.badge > 0 && (
              <span style={{ position:'absolute', top:4, right:6, minWidth:16, height:16, borderRadius:8, background:'#e87f7f', color:'#fff', fontSize:10, fontWeight:700, display:'flex', alignItems:'center', justifyContent:'center', padding:'0 4px' }}>
                {a.badge > 9 ? '9+' : a.badge}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Content */}
      <div style={{ flex:1, overflowY:'auto', paddingBottom:80 }}>

        {aba === 'demandas' && (
          <div style={{ padding:'0 14px' }}>
            {demandas.length === 0 && (
          <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'32px 20px', textAlign:'center' }}>
            <img src={EMPTY_DEMAND_GIF} alt="Sem demandas" style={{ width:'65%', maxWidth:240, marginBottom:16, borderRadius:12 }} />
            <div style={{ fontFamily:'var(--font-display)', fontSize:17, fontWeight:700, color:'var(--cream)', marginBottom:6 }}>Sem demanda ainda!</div>
            {isCoord && <div style={{ fontSize:13, color:'var(--muted)' }}>Clique em "+ Demanda" para criar uma!</div>}
          </div>
        )}
            {demandas.map(d => {
              const meuEnvio = meusEnvios.find(e=>e.demandaId===d.id);
              return <DemandaCard key={d.id} demanda={d} user={user} meuEnvio={meuEnvio} />;
            })}
          </div>
        )}

        {aba === 'avaliar' && isCoord && <PainelCoordenador user={user} />}
      </div>
      {modalDemanda && <NovaDemandaModal user={user} onClose={()=>setModalDemanda(false)} />}
    </div>
  );
}

function EmptyState({ icon, msg }) {
  return (
    <div style={{ textAlign:'center', padding:'48px 20px' }}>
      <div style={{ fontSize:40, marginBottom:12 }}>{icon}</div>
      <div style={{ fontSize:14, color:'var(--muted)', lineHeight:1.7 }}>{msg}</div>
    </div>
  );
}

function authorRow(user) {
  return (
    <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:14 }}>
      <div style={avatarCircle(40)}>{user.nome[0]}</div>
      <div>
        <div style={{ fontSize:14, fontWeight:700, color:'var(--cream)' }}>{user.nome}</div>
        <div style={{ fontSize:12, color:'var(--gold)' }}>{user.cargo}</div>
      </div>
    </div>
  );
}

